//=====================================================================================
// Moon phase calculation
//
// This program is based on "phase.c" attached to the following page:
// http://www.voidware.com/moon_phase.htm
// The page can be found by searching for "www.voidware.com/moon_phase.htm"
// on Internet Archive (https://web.archive.org/).
//=====================================================================================
#include <math.h>

#define M_RAD         (M_PI / 180.0f)
#define SMALL_FLOAT   (1e-5f)
#define SYNODIC_MONTH (29.53059f)

static float Julian(int year, int month, float day) {
  int a, b = 0, c, e;
  if (month < 3) {
    year--;
    month += 12;
  }
  if (year > 1582 || (year == 1582 && month > 10) || (year == 1582 && month == 10 && day > 15)) {
    a = year / 100;
    b = 2 - a + a / 4;
  }
  c = 365.25f * year;
  e = 30.6001f * (month + 1);
  return b + c + e + day + 1720994.5f;
}

static float sun_position(float j) {
  float n, x, e, l, dl, v;
  int i;

  n = 360.0f / 365.2422f * j;
  i = n / 360;
  n = n - i * 360.0f;
  x = n - 3.762863f;
  if (x < 0) x += 360.0f;
  x *= M_RAD;
  e = x;
  do {
    dl = e - .016718f * sin(e) - x;
    e = e - dl / (1 - .016718f * cos(e));
  } while (fabs(dl) >= SMALL_FLOAT);
  v = 360 / M_PI * atan(1.01686011182f * tan(e / 2));
  l = v + 282.596403f;
  i = l / 360;
  l = l - i * 360.0f;
  return l;
}

static float moon_position(float j, float ls) {
  float ms, l, mm, n, ev, sms, ae, ec;
  int i;

  /* ls = sun_position(j) */
  ms = 0.985647332099f * j - 3.762863f;
  if (ms < 0) ms += 360.0f;
  l = 13.176396 * j + 64.975464f;
  i = l / 360;
  l = l - i * 360.0f;
  if (l < 0) l += 360.0f;
  mm = l - 0.1114041f * j - 349.383063f;
  i = mm / 360;
  mm -= i * 360.0f;
  n = 151.950429f - 0.0529539f * j;
  i = n / 360;
  n -= i * 360.0f;
  ev = 1.2739f * sin((2.0f * (l - ls) - mm) * M_RAD);
  sms = sin(ms * M_RAD);
  ae = 0.1858f * sms;
  mm += ev - ae - 0.37f * sms;
  ec = 6.2886f * sin(mm * M_RAD);
  l += ev + ec - ae + 0.214f * sin(2.0f * mm * M_RAD);
  l = 0.6583f * sin(2.0f * (l - ls) * M_RAD) + l;
  return l;
}

float calc_moon_phase(int year, int month, int day) {
  float hour = 0.0f;

  float j = Julian(year, month, (float)day + hour / 24.0f) - 2444238.5f;
  float ls = sun_position(j);
  float lm = moon_position(j, ls);

  float t = lm - ls;
  if (t < 0) t += 360.0f;
  
  return t / 360.0f; // 0.0 - 1.0
}

//-------------------------------------------------------------------------------------
//
//-------------------------------------------------------------------------------------
float get_moon_age(float phase) {
  return phase * SYNODIC_MONTH;
}

//-------------------------------------------------------------------------------------
//
//-------------------------------------------------------------------------------------
const unsigned char* get_phase_image(float phase, bool northern) {
  uint32_t n = sizeof(moonphase) / sizeof(moonphase[0]);
  uint32_t i = (uint32_t)(phase * (float)n) % n;
  return moonphase[northern ? i : (n - 1) - i];
}

//-------------------------------------------------------------------------------------
//
//-------------------------------------------------------------------------------------
const unsigned char* get_phase_image(int n) {
  return ((0 <= n && n < sizeof(moonphase) / sizeof(moonphase[0])) ? moonphase[n] : NULL);
}